import { useCallback, useEffect, useRef, useState } from 'react';
import { OfflineError, fetchSinglePerson, searchPersons } from '../services/elasticSearchService';
import { fetchOnlinePersons } from '../services/onlineService';
import { searchOffline } from '../services/offlineService';
import { mergeResults } from '../utils/mergeResults';
import type {
  PersonLocatorProps,
  PersonResult,
  PersonType,
  PagingState,
  SearchResults,
} from '../types';
import { useDebounce } from './useDebounce';
import { usePaging } from './usePaging';

export interface UsePersonSearchReturn {
  results: SearchResults;
  isLoading: boolean;
  isLoadingMore: boolean;
  isOffline: boolean;
  error: string | null;
  selectedPerson: PersonResult | null;
  inputValue: string;
  activeTab: PersonType;
  pagingState: PagingState;
  setInputValue: (v: string) => void;
  setActiveTab: (tab: PersonType) => void;
  selectPerson: (person: PersonResult) => void;
  clearSelection: () => void;
  loadMore: (tab: PersonType) => void;
}

const emptyResults: SearchResults = {
  prisoners: [],
  guards: [],
  civilians: [],
  totalCount: 0,
};

function firstTabWithResults(results: SearchResults): PersonType {
  if (results.prisoners.length > 0) return 'prisoner';
  if (results.guards.length > 0) return 'guard';
  return 'civilian';
}

export function usePersonSearch(props: PersonLocatorProps): UsePersonSearchReturn {
  const {
    serviceConfig,
    type,
    minChars = 3,
    onSelect,
    filters = [],
    additionalSearchFields = [],
    additionalResultFields = [],
    enableOfflineSearch = false,
    singleSearch,
    state,
    clearData,
    activeOnly,
    isDefaultActive,
  } = props;

  const pageSize = serviceConfig.pageSize ?? 3;

  const [inputValue, setInputValueState] = useState('');
  const [results, setResults] = useState<SearchResults>(emptyResults);
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [isOffline, setIsOffline] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedPerson, setSelectedPerson] = useState<PersonResult | null>(null);
  const [activeTab, setActiveTabState] = useState<PersonType>(type ?? 'prisoner');
  const [showActiveOnly, setShowActiveOnly] = useState(isDefaultActive ?? false);

  const { pagingState, advance, setHasMore, reset: resetPaging } = usePaging();

  const abortControllers = useRef<AbortController[]>([]);
  const debouncedInput = useDebounce(inputValue, 300);

  // Controlled state prop
  useEffect(() => {
    if (state !== undefined) {
      setSelectedPerson(state);
    }
  }, [state]);

  // singleSearch: fetch on mount
  useEffect(() => {
    if (!singleSearch) return;
    const controller = new AbortController();
    fetchSinglePerson({
      key: singleSearch.key,
      value: singleSearch.value,
      personType: type,
      config: serviceConfig,
      signal: controller.signal,
    })
      .then((person) => {
        if (person) setSelectedPerson(person);
      })
      .catch(() => {/* silently ignore */});
    return () => controller.abort();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const cancelPendingRequests = useCallback(() => {
    abortControllers.current.forEach((c) => c.abort());
    abortControllers.current = [];
  }, []);

  const effectiveActiveOnly =
    activeOnly !== undefined ? activeOnly : showActiveOnly;

  const runSearch = useCallback(
    async (query: string, isLoadMore = false, loadMoreTab?: PersonType) => {
      cancelPendingRequests();

      const controllers = [
        new AbortController(),
        new AbortController(),
        new AbortController(),
        new AbortController(),
      ];
      abortControllers.current = controllers;

      if (!isLoadMore) {
        setIsLoading(true);
        setError(null);
        setIsOffline(false);
        resetPaging();
      } else {
        setIsLoadingMore(true);
      }

      const types: PersonType[] = type
        ? [type]
        : ['prisoner', 'guard', 'civilian'];

      const baseOffset = isLoadMore && loadMoreTab
        ? pagingState[loadMoreTab === 'prisoner' ? 'prisoners' : loadMoreTab === 'guard' ? 'guards' : 'civilians'].offset
        : 0;

      // Build ES promises per category
      const esPromises = (['prisoner', 'guard', 'civilian'] as PersonType[]).map((pt, i) => {
        if (!types.includes(pt)) {
          return Promise.resolve(null);
        }
        if (isLoadMore && loadMoreTab !== pt) {
          return Promise.resolve(null);
        }
        return searchPersons({
          query,
          personType: pt,
          filters,
          additionalSearchFields,
          additionalResultFields,
          offset: isLoadMore ? baseOffset : 0,
          pageSize,
          activeOnly: effectiveActiveOnly,
          config: serviceConfig,
          signal: controllers[i].signal,
        });
      });

      // Online service promise
      const onlinePromise = fetchOnlinePersons({
        query,
        personType: type,
        config: serviceConfig,
        signal: controllers[3].signal,
      });

      const [prisonerSettled, guardSettled, civilianSettled, onlineSettled] =
        await Promise.allSettled([...esPromises, onlinePromise]);

      const onlineResults: PersonResult[] =
        onlineSettled.status === 'fulfilled' && Array.isArray(onlineSettled.value)
          ? (onlineSettled.value as PersonResult[])
          : [];

      // Check if all ES calls failed with OfflineError
      const esSettled = [prisonerSettled, guardSettled, civilianSettled];
      const allOffline = esSettled
        .filter((_, i) => types.includes((['prisoner', 'guard', 'civilian'] as PersonType[])[i]))
        .every(
          (s) => s.status === 'rejected' && s.reason instanceof OfflineError
        );

      if (allOffline && enableOfflineSearch) {
        setIsOffline(true);
        try {
          const offlineController = new AbortController();
          abortControllers.current.push(offlineController);
          const offlineResults = await searchOffline({
            query,
            personType: type,
            config: serviceConfig,
            signal: offlineController.signal,
          });

          const grouped = groupByType(offlineResults);
          setResults({
            ...grouped,
            totalCount: offlineResults.length,
          });
        } catch {
          setError('חיפוש לא מקוון נכשל');
        }
        setIsLoading(false);
        setIsLoadingMore(false);
        return;
      }

      // Extract ES results per type
      const getESResult = (
        settled: PromiseSettledResult<unknown>
      ): { results: PersonResult[]; hasMore: boolean } | null => {
        if (settled.status === 'fulfilled' && settled.value !== null) {
          return settled.value as { results: PersonResult[]; hasMore: boolean };
        }
        return null;
      };

      const prisonerES = getESResult(prisonerSettled);
      const guardES = getESResult(guardSettled);
      const civilianES = getESResult(civilianSettled);

      const prisonerMerged = mergeResults(
        prisonerES?.results ?? [],
        onlineResults.filter((p) => p.personType === 'prisoner')
      );
      const guardMerged = mergeResults(
        guardES?.results ?? [],
        onlineResults.filter((p) => p.personType === 'guard')
      );
      const civilianMerged = mergeResults(
        civilianES?.results ?? [],
        onlineResults.filter((p) => p.personType === 'civilian')
      );

      if (isLoadMore && loadMoreTab) {
        setResults((prev) => {
          const key = loadMoreTab === 'prisoner' ? 'prisoners'
            : loadMoreTab === 'guard' ? 'guards' : 'civilians';
          const newArr = loadMoreTab === 'prisoner' ? prisonerMerged
            : loadMoreTab === 'guard' ? guardMerged : civilianMerged;
          const merged = [...prev[key], ...newArr];
          const total = merged.length +
            (loadMoreTab === 'prisoner' ? prev.guards.length + prev.civilians.length :
             loadMoreTab === 'guard' ? prev.prisoners.length + prev.civilians.length :
             prev.prisoners.length + prev.guards.length);
          return { ...prev, [key]: merged, totalCount: total };
        });

        const hasMore = loadMoreTab === 'prisoner' ? (prisonerES?.hasMore ?? false)
          : loadMoreTab === 'guard' ? (guardES?.hasMore ?? false)
          : (civilianES?.hasMore ?? false);
        advance(loadMoreTab, pageSize, hasMore);
      } else {
        const newResults: SearchResults = {
          prisoners: prisonerMerged,
          guards: guardMerged,
          civilians: civilianMerged,
          totalCount: prisonerMerged.length + guardMerged.length + civilianMerged.length,
        };
        setResults(newResults);

        // Update hasMore per category
        if (prisonerES) setHasMore('prisoner', prisonerES.hasMore);
        if (guardES) setHasMore('guard', guardES.hasMore);
        if (civilianES) setHasMore('civilian', civilianES.hasMore);

        // Set active tab to first category with results
        setActiveTabState(firstTabWithResults(newResults));

        // Handle general errors if any ES call failed with non-OfflineError
        const anyError = esSettled.find(
          (s) => s.status === 'rejected' && !(s.reason instanceof OfflineError)
        );
        if (anyError && anyError.status === 'rejected') {
          setError(`שגיאת חיפוש: ${anyError.reason?.message ?? 'שגיאה לא ידועה'}`);
        }
      }

      setIsLoading(false);
      setIsLoadingMore(false);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      cancelPendingRequests, enableOfflineSearch, filters, additionalSearchFields,
      additionalResultFields, pageSize, serviceConfig, type, effectiveActiveOnly,
    ]
  );

  // Fire search when debounced input changes
  useEffect(() => {
    if (debouncedInput.length < minChars) return;
    runSearch(debouncedInput);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [debouncedInput, minChars]);

  // Cleanup on unmount
  useEffect(() => {
    return () => cancelPendingRequests();
  }, [cancelPendingRequests]);

  const setInputValue = useCallback((v: string) => {
    setInputValueState(v);
    if (v.length < minChars) {
      setResults(emptyResults);
      setError(null);
      setIsOffline(false);
    }
  }, [minChars]);

  const setActiveTab = useCallback((tab: PersonType) => {
    setActiveTabState(tab);
  }, []);

  const selectPerson = useCallback(
    (person: PersonResult) => {
      setSelectedPerson(person);
      onSelect?.(person);
    },
    [onSelect]
  );

  const clearSelection = useCallback(() => {
    setInputValueState('');
    setResults(emptyResults);
    setSelectedPerson(null);
    setError(null);
    setIsOffline(false);
    resetPaging();
    clearData?.();
  }, [clearData, resetPaging]);

  const loadMore = useCallback(
    (tab: PersonType) => {
      if (debouncedInput.length < minChars) return;
      const key = tab === 'prisoner' ? 'prisoners' : tab === 'guard' ? 'guards' : 'civilians';
      if (!pagingState[key].hasMore || isLoadingMore) return;
      runSearch(debouncedInput, true, tab);
    },
    [debouncedInput, minChars, pagingState, isLoadingMore, runSearch]
  );

  return {
    results,
    isLoading,
    isLoadingMore,
    isOffline,
    error,
    selectedPerson,
    inputValue,
    activeTab,
    pagingState,
    setInputValue,
    setActiveTab,
    selectPerson,
    clearSelection,
    loadMore,
  };
}

function groupByType(persons: PersonResult[]): Omit<SearchResults, 'totalCount'> {
  return {
    prisoners: persons.filter((p) => p.personType === 'prisoner'),
    guards: persons.filter((p) => p.personType === 'guard'),
    civilians: persons.filter((p) => p.personType === 'civilian'),
  };
}
