import React from 'react';
import type { PersonLocatorProps } from '../types';
import { usePersonSearch } from '../hooks/usePersonSearch';
import SearchInput from './SearchInput';
import ResultsPanel from './ResultsPanel';

const PersonLocator: React.FC<PersonLocatorProps> = (props) => {
  const {
    type,
    disabled,
    resultDirection = 'down',
    minChars = 3,
    additionalResultFields = [],
    openTikAsir,
    navigate,
    HidePhotosSugAdam,
    HideMishmorot,
    hideNavigationLinks,
    activeOnly,
    isDefaultActive,
  } = props;

  const {
    results,
    isLoading,
    isLoadingMore,
    isOffline,
    error,
    selectedPerson,
    inputValue,
    activeTab,
    setInputValue,
    setActiveTab,
    selectPerson,
    clearSelection,
    loadMore,
  } = usePersonSearch(props);

  const showResults =
    inputValue.length >= minChars || selectedPerson !== null;

  const showTabBar = !type;

  const handleSelectPerson = (person: typeof selectedPerson) => {
    if (person) selectPerson(person);
  };

  return (
    <div
      className="relative w-full font-sans"
      dir="rtl"
      aria-disabled={disabled}
      style={disabled ? { pointerEvents: 'none' } : undefined}
    >
      <SearchInput
        inputValue={inputValue}
        onInputChange={setInputValue}
        onClear={clearSelection}
        disabled={disabled}
        type={type}
        activeOnly={activeOnly}
        isDefaultActive={isDefaultActive}
        minChars={minChars}
      />

      {error && (
        <div
          className="mt-1 text-xs text-red-600 text-right"
          role="alert"
          aria-live="assertive"
        >
          {error}
          <button
            type="button"
            onClick={() => setInputValue(inputValue)}
            className="mr-2 underline focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:outline-none"
            aria-label="נסה שוב"
          >
            נסה שוב
          </button>
        </div>
      )}

      {showResults && (
        <ResultsPanel
          results={results}
          isLoading={isLoading}
          isLoadingMore={isLoadingMore}
          isOffline={isOffline}
          activeTab={activeTab}
          query={inputValue}
          resultDirection={resultDirection}
          showTabBar={showTabBar}
          onTabChange={setActiveTab}
          onSelect={(person) => handleSelectPerson(person)}
          loadMore={loadMore}
          openTikAsir={openTikAsir}
          navigate={navigate}
          HidePhotosSugAdam={HidePhotosSugAdam}
          HideMishmorot={HideMishmorot}
          hideNavigationLinks={hideNavigationLinks}
          additionalResultFields={additionalResultFields}
        />
      )}
    </div>
  );
};

export default PersonLocator;
