import React, { useId, useState } from 'react';
import type { PersonLocatorProps, PersonType } from '../types';

interface SearchInputProps {
  inputValue: string;
  onInputChange: (v: string) => void;
  onClear: () => void;
  disabled?: boolean;
  type?: PersonType;
  activeOnly?: PersonLocatorProps['activeOnly'];
  isDefaultActive?: PersonLocatorProps['isDefaultActive'];
  minChars?: number;
  onActiveToggle?: (active: boolean) => void;
  activeToggleValue?: boolean;
}

const TYPE_LABELS: Record<PersonType, string> = {
  prisoner: 'אסירים',
  guard: 'סוהרים',
  civilian: 'אזרחים',
};

const SearchInput: React.FC<SearchInputProps> = ({
  inputValue,
  onInputChange,
  onClear,
  disabled,
  type,
  activeOnly,
  isDefaultActive,
  minChars = 3,
  onActiveToggle,
  activeToggleValue,
}) => {
  const toggleId = useId();
  const [showTypeTooltip, setShowTypeTooltip] = useState(false);
  const [internalActive, setInternalActive] = useState(isDefaultActive ?? false);

  const isActive = activeToggleValue !== undefined ? activeToggleValue : internalActive;

  const handleToggle = () => {
    const next = !isActive;
    setInternalActive(next);
    onActiveToggle?.(next);
  };

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2 border border-gray-300 rounded-lg px-3 py-2 bg-white focus-within:ring-2 focus-within:ring-blue-500">
        {/* Magnifying glass icon */}
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="16"
          height="16"
          viewBox="0 0 24 24"
          fill="none"
          stroke="#2563EB"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="flex-shrink-0"
          aria-hidden="true"
        >
          <circle cx="11" cy="11" r="8" />
          <line x1="21" y1="21" x2="16.65" y2="16.65" />
        </svg>

        {/* Text input */}
        <input
          type="text"
          value={inputValue}
          onChange={(e) => onInputChange(e.target.value)}
          placeholder="חיפוש אדם..."
          disabled={disabled}
          dir="rtl"
          className="flex-1 outline-none text-right text-sm text-gray-900 placeholder-gray-400 disabled:cursor-not-allowed bg-transparent"
          aria-label="חיפוש אדם"
          aria-disabled={disabled}
        />

        {/* Type filter button — hidden in single-type mode */}
        {!type && (
          <div className="relative">
            <button
              type="button"
              onMouseEnter={() => setShowTypeTooltip(true)}
              onMouseLeave={() => setShowTypeTooltip(false)}
              onFocus={() => setShowTypeTooltip(true)}
              onBlur={() => setShowTypeTooltip(false)}
              disabled={disabled}
              className="text-gray-400 hover:text-gray-600 focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:outline-none min-h-[44px] min-w-[44px] flex items-center justify-center rounded"
              aria-label="סנן לפי סוג"
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="14"
                height="14"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                aria-hidden="true"
              >
                <line x1="4" y1="6" x2="20" y2="6" />
                <line x1="8" y1="12" x2="16" y2="12" />
                <line x1="12" y1="18" x2="12" y2="18" />
              </svg>
            </button>
            {showTypeTooltip && (
              <div
                className="absolute bottom-full mb-1 right-0 bg-gray-800 text-white text-xs rounded px-2 py-1 whitespace-nowrap z-10"
                role="tooltip"
              >
                {type ? TYPE_LABELS[type] : 'כל הסוגים'}
              </div>
            )}
          </div>
        )}

        {/* Clear button */}
        {inputValue !== '' && (
          <button
            type="button"
            onClick={onClear}
            disabled={disabled}
            className="text-gray-400 hover:text-gray-600 focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:outline-none min-h-[44px] min-w-[44px] flex items-center justify-center rounded"
            aria-label="נקה חיפוש"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="14"
              height="14"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              aria-hidden="true"
            >
              <line x1="18" y1="6" x2="6" y2="18" />
              <line x1="6" y1="6" x2="18" y2="18" />
            </svg>
          </button>
        )}
      </div>

      {/* Active-only toggle — hidden when activeOnly prop is explicitly set */}
      {activeOnly === undefined && (
        <div className="flex items-center justify-end gap-2">
          <label
            htmlFor={toggleId}
            className="text-sm text-gray-700 cursor-pointer select-none"
          >
            פעילים בלבד
          </label>
          <button
            id={toggleId}
            type="button"
            role="switch"
            aria-checked={isActive}
            onClick={handleToggle}
            disabled={disabled}
            className={[
              'relative inline-flex h-5 w-9 items-center rounded-full transition-colors focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:outline-none min-h-[44px]',
              isActive ? 'bg-blue-600' : 'bg-gray-300',
              disabled ? 'cursor-not-allowed opacity-50' : 'cursor-pointer',
            ].join(' ')}
            aria-label="פעילים בלבד"
          >
            <span
              className={[
                'inline-block h-3 w-3 rounded-full bg-white shadow transition-transform',
                isActive ? 'translate-x-5' : 'translate-x-1',
              ].join(' ')}
            />
          </button>
        </div>
      )}

      {/* Hint when input is too short */}
      {inputValue.length > 0 && inputValue.length < minChars && (
        <p className="text-gray-500 text-xs text-right" role="status" aria-live="polite">
          הקלד לפחות {minChars} תווים לחיפוש
        </p>
      )}
    </div>
  );
};

export default SearchInput;
