import React from 'react';
import type { PersonLocatorProps, PersonResult } from '../types';
import { highlightMatch } from '../utils/highlightMatch';

interface ResultCardProps {
  person: PersonResult;
  query: string;
  isLast?: boolean;
  lastRef?: (node: HTMLElement | null) => void;
  onSelect: (person: PersonResult) => void;
  openTikAsir?: PersonLocatorProps['openTikAsir'];
  navigate?: PersonLocatorProps['navigate'];
  HidePhotosSugAdam?: PersonLocatorProps['HidePhotosSugAdam'];
  HideMishmorot?: PersonLocatorProps['HideMishmorot'];
  hideNavigationLinks?: PersonLocatorProps['hideNavigationLinks'];
  additionalResultFields?: string[];
}

const ResultCard: React.FC<ResultCardProps> = ({
  person,
  query,
  isLast,
  lastRef,
  onSelect,
  openTikAsir,
  navigate,
  HidePhotosSugAdam,
  HideMishmorot,
  hideNavigationLinks,
  additionalResultFields = [],
}) => {
  const showPhoto =
    Boolean(person.photoUrl) &&
    !(HidePhotosSugAdam ?? []).includes(person.personType);

  const handleClick = () => onSelect(person);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onSelect(person);
    }
  };

  return (
    <div
      ref={isLast ? lastRef : undefined}
      className="flex items-start gap-3 p-3 hover:bg-gray-50 cursor-pointer transition-all duration-150 animate-fadeIn"
      role="option"
      aria-label={person.fullName}
      aria-selected={false}
      tabIndex={0}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
    >
      {/* Photo */}
      {showPhoto && (
        <img
          src={person.photoUrl}
          alt={person.fullName}
          className="w-10 h-10 rounded-full object-cover flex-shrink-0"
        />
      )}
      {!showPhoto && (
        <div
          className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center flex-shrink-0"
          aria-hidden="true"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="currentColor"
            className="text-gray-400"
          >
            <path d="M12 12c2.7 0 4.8-2.1 4.8-4.8S14.7 2.4 12 2.4 7.2 4.5 7.2 7.2 9.3 12 12 12zm0 2.4c-3.2 0-9.6 1.6-9.6 4.8v2.4h19.2v-2.4c0-3.2-6.4-4.8-9.6-4.8z" />
          </svg>
        </div>
      )}

      {/* Info */}
      <div className="flex-1 min-w-0">
        {/* Full name with highlight */}
        <p className="text-gray-900 text-sm font-medium text-right truncate">
          {highlightMatch(person.fullName, query)}
        </p>

        {/* Secondary: id / prisoner number / rank */}
        <p className="text-gray-500 text-xs text-right mt-0.5">
          {[person.idNumber, person.prisonerNumber, person.rank]
            .filter(Boolean)
            .join(' · ')}
        </p>

        {/* Tertiary: unit / phone */}
        <p className="text-gray-500 text-xs text-right mt-0.5">
          {[person.unit, !HideMishmorot ? person.phone : undefined]
            .filter(Boolean)
            .join(' · ')}
        </p>

        {/* Additional fields */}
        {additionalResultFields.map((field) => {
          const val = person.additionalFields?.[field];
          if (val === undefined || val === null) return null;
          return (
            <p key={field} className="text-gray-500 text-xs text-right mt-0.5">
              {field}: {String(val)}
            </p>
          );
        })}

        {/* Navigation buttons */}
        {!hideNavigationLinks && (
          <div className="flex gap-2 mt-2 justify-end" onClick={(e) => e.stopPropagation()}>
            {person.personType === 'prisoner' && openTikAsir && (
              <button
                type="button"
                onClick={() => openTikAsir(person)}
                className="text-xs text-blue-600 hover:text-blue-800 focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:outline-none min-h-[44px] min-w-[44px] px-2"
                aria-label={`תיק אסיר עבור ${person.fullName}`}
              >
                תיק אסיר
              </button>
            )}
            {navigate && (
              <button
                type="button"
                onClick={() => navigate(`/person/${person.id}`)}
                className="text-xs text-blue-600 hover:text-blue-800 focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:outline-none min-h-[44px] min-w-[44px] px-2"
                aria-label={`נווט לפרופיל ${person.fullName}`}
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="14"
                  height="14"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  aria-hidden="true"
                >
                  <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" />
                  <polyline points="15 3 21 3 21 9" />
                  <line x1="10" y1="14" x2="21" y2="3" />
                </svg>
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default ResultCard;
