import React from 'react';
import type { PersonResult, PersonType, SearchResults } from '../types';

interface TabBarProps {
  results: SearchResults;
  activeTab: PersonType;
  isLoading: boolean;
  onTabChange: (tab: PersonType) => void;
}

const TABS: { type: PersonType; label: string }[] = [
  { type: 'prisoner', label: 'אסירים' },
  { type: 'guard', label: 'סוהרים' },
  { type: 'civilian', label: 'אזרחים' },
];

const getResults = (results: SearchResults, type: PersonType): PersonResult[] => {
  if (type === 'prisoner') return results.prisoners;
  if (type === 'guard') return results.guards;
  return results.civilians;
};

const TabBar: React.FC<TabBarProps> = ({ results, activeTab, isLoading, onTabChange }) => {
  const visibleTabs = TABS.filter(
    (tab) => isLoading || getResults(results, tab.type).length > 0
  );

  if (visibleTabs.length === 0) return null;

  return (
    <div
      className="flex border-b border-gray-200"
      role="tablist"
      aria-label="קטגוריות תוצאות"
    >
      {visibleTabs.map((tab) => {
        const count = getResults(results, tab.type).length;
        const isActive = activeTab === tab.type;
        return (
          <button
            key={tab.type}
            role="tab"
            aria-selected={isActive}
            aria-controls={`panel-${tab.type}`}
            className={[
              'flex items-center gap-1.5 px-4 py-2 text-sm transition-colors focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:outline-none min-h-[44px]',
              isActive
                ? 'border-b-2 border-blue-600 text-blue-600 font-medium'
                : 'text-gray-500 hover:text-gray-700',
            ].join(' ')}
            onClick={() => onTabChange(tab.type)}
          >
            <span>{tab.label}</span>
            {count > 0 && (
              <span
                className={`text-xs px-1.5 py-0.5 rounded-full ${
                  isActive
                    ? 'bg-blue-100 text-blue-700'
                    : 'bg-gray-100 text-gray-600'
                }`}
              >
                {count}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
};

export default TabBar;
